// Node.js Express Redirects

// 1. Permanent Redirect (SEO friendly!)
app.get('/old-blog-post', (req, res) => {
  // Sends a 301 status code
  res.redirect(301, '/new-blog-post');
});

// 2. Temporary Redirect (Auth checks)
app.get('/admin-dashboard', (req, res) => {
  if (!req.user) {
    // Sends a 302 status code by default in Express
    res.redirect('/login');
  }
});
